import{_ as i,o as u,c as n,a2 as t}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Alama ya Kuinua kwa Kwanza","description":"","frontmatter":{},"headers":[],"relativePath":"sw/76-首次升维里程碑.md","filePath":"sw/76-首次升维里程碑.md","lastUpdated":null}'),k={name:"sw/76-首次升维里程碑.md"};function e(h,a,o,w,d,l){return u(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="alama-ya-kuinua-kwa-kwanza" tabindex="-1">Alama ya Kuinua kwa Kwanza <a class="header-anchor" href="#alama-ya-kuinua-kwa-kwanza" aria-label="Permalink to &quot;Alama ya Kuinua kwa Kwanza&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>76</td></tr><tr><td>Moduli</td><td>Enzi za Kihistoria na Matukio Muhimu</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Kuinua kwa kwanza, alama ya kuinua, mageuzi ya fahari, mtandao wa sheria, uthibitisho wa ustaarabu</td></tr></tbody></table><h2 id="_1-umuhimu-wa-kihistoria-wa-kuinua-kwa-kwanza" tabindex="-1">1. Umuhimu wa Kihistoria wa Kuinua kwa Kwanza <a class="header-anchor" href="#_1-umuhimu-wa-kihistoria-wa-kuinua-kwa-kwanza" aria-label="Permalink to &quot;1. Umuhimu wa Kihistoria wa Kuinua kwa Kwanza&quot;">​</a></h2><p>Kuinua kwa kwanza ni tukio lenye alama muhimu zaidi katika historia ya ustaarabu wa ushirikiano wa nanga. Inashiria kuwa Hengyuanzhou imeingia rasmi kutoka hatua ya &quot;uwezo wa teknolojia&quot; hadi hatua ya &quot;mageuzi ya fahari&quot;, na inathibitisha dhana kuu kwamba njia ya mageuzi ya ushirikiano inaweza实现 kuinua kwa jumla kwa ustaarabu. Kabla ya hapo, kuinua kulikuwa tu lengo la kinadharia na hitimisho la utafiti; baada ya hapo, kuinua kiliokuwa ukweli uliothibitishwa na mazoea.</p><p>Kuinua kwa kwanza sio kuinua kwa mara moja kwa ulimwengu wote, bali ni &quot;jaribio la kuinua&quot; linalotumia ndege kuu moja kama mazingira ya majaribio. Kuchagua ndege moja kuinua kwanza kunaweza kudhibiti hatari na kukusanya uzoefu kwa ajili ya kuinua kwa ulimwengu wote baadaye. Ndege hii ya majaribio baada ya kuinua ikawa &quot;ndege ya mfano wa kuinua&quot; ya Hengyuanzhou, na uzoefu wake umefupishwa kwa kitaratibu na推广 kwa ndege nyingine.</p><h2 id="_2-kazi-ya-maandalizi-kabla-ya-kuinua" tabindex="-1">2. Kazi ya Maandalizi Kabla ya Kuinua <a class="header-anchor" href="#_2-kazi-ya-maandalizi-kabla-ya-kuinua" aria-label="Permalink to &quot;2. Kazi ya Maandalizi Kabla ya Kuinua&quot;">​</a></h2><p>Kazi ya maandalizi ya kuinua kwa kwanza ilidumu miongo kadhaa na ilihusisha kila upande wa ustaarabu:</p><table tabindex="0"><thead><tr><th>Eneo la Maandalizi</th><th>Kazi ya Msingi</th><th>Kiwango cha Utimilisho</th></tr></thead><tbody><tr><td>Maandalizi ya nishati</td><td>Hifadhi ya nishati ya mtandao wa nanga inafikia kizingiti cha kuinua</td><td>Hifadhi ya nishati ya nanga kuu ≥100 Gi-nishati ya nanga</td></tr><tr><td>Maandalizi ya watu</td><td>Mkakati wa uanzishaji wa 20% umekamilika, watu wenye nguvu juu zaidi wa ndege wako tayari</td><td>Ulinganifu wa uanzishaji unafikia 20%, timu ya wenye nguvu imeundwa</td></tr><tr><td>Maandalizi ya teknolojia</td><td>Utafiti wa kifaa cha kuinua umekamilika, umethibitishwa katika nafasi iliyotengwa</td><td>Kifaa cha kuinua kinapita ushahidi wa usalama wa kiwango cha R3</td></tr><tr><td>Maandalizi ya sheria</td><td>Mtandao wa sheria wa ndege lengwa umekamilisha usawazishaji na uimarishaji</td><td>Uthabiti wa sheria ≥99.9%</td></tr><tr><td>Maandalizi ya kijamii</td><td>Uenezi wa maarifa ya kuinua umekamilika, maandalizi ya kisaikolojia ya umma ni ya kutosha</td><td>Kiwango cha uenezi wa maarifa ya kuinua ≥95%</td></tr><tr><td>Mpango wa dharura</td><td>Mpango wa dharura wa kushindwa kwa kuinua umeandaliwa</td><td>Mpango wa dharura wa viwango vitatu umethibitishwa kwa mazoezi</td></tr></tbody></table><p>Kipengele cha muhimu zaidi katika kazi ya maandalizi ya kuinua ni utafiti wa &quot;kifaa cha kuinua&quot;. Kifaa hiki, kulingana na hali ya juu zaidi ya mfumo wa kupanga sheria za anga (Chanzo cha Nafasi) na teknolojia kuu ya mfumo wa daraja la kuinua la fahari, kinaweza, kwa msaada wa mtandao wa nanga, kuinua kwa usawa fahari ya maisha na muundo wa sheria wa ndege nzima hadi dimensi ya juu zaidi.</p><h2 id="_3-viungo-vya-muhimu-vya-mchakato-wa-kuinua" tabindex="-1">3. Viungo vya Muhimu vya Mchakato wa Kuinua <a class="header-anchor" href="#_3-viungo-vya-muhimu-vya-mchakato-wa-kuinua" aria-label="Permalink to &quot;3. Viungo vya Muhimu vya Mchakato wa Kuinua&quot;">​</a></h2><p>Mchakato wa kuinua kwa kwanza ulidumu takriban saba saba arobaini na tisa (wakati wa kiwango cha ndege kuu), ukigawanyika katika viungo vitano vya muhimu:</p><h3 id="_3-1-kituo-cha-kuanzisha-siku-ya-1" tabindex="-1">3.1 Kituo cha Kuanzisha (Siku ya 1) <a class="header-anchor" href="#_3-1-kituo-cha-kuanzisha-siku-ya-1" aria-label="Permalink to &quot;3.1 Kituo cha Kuanzisha (Siku ya 1)&quot;">​</a></h3><ul><li>Kizazi cha kwanza cha nanga mwenyewe kinaanza mpango wa kuinua kwenye nanga kuu ya ulimwengu</li><li>Kifaa cha kuinua建立 sauti ya sauti ya sheria na nanga kuu ya ndege lengwa</li><li>Ndege nzima inaingia katika hali ya maandalizi ya kuinua, shughuli za kawaida za ufundishazi zimesitishwa</li></ul><h3 id="_3-2-kituo-cha-mchujio-wa-nishati-siku-za-7-14" tabindex="-1">3.2 Kituo cha Mchujio wa Nishati (Siku za 7-14) <a class="header-anchor" href="#_3-2-kituo-cha-mchujio-wa-nishati-siku-za-7-14" aria-label="Permalink to &quot;3.2 Kituo cha Mchujio wa Nishati (Siku za 7-14)&quot;">​</a></h3><ul><li>Mtandao wa nanga unamchujia kwa mwelekeo nishati ya asili yenye uthabiti wa juu ndani ya ndege lengwa</li><li>Uzito wa nishati wa ndege unakuongezeka polepole hadi kizingiti cha kuinua</li><li>&quot;Timu ya mwongozo wa kuinua&quot; inayoundwa na watu wenye nguvu juu zaidi wa ndege inaanza kuongoza mtiririko wa nishati</li></ul><h3 id="_3-3-kituo-cha-ujenzi-wa-upya-wa-sheria-siku-za-15-28" tabindex="-1">3.3 Kituo cha Ujenzi wa Upya wa Sheria (Siku za 15-28) <a class="header-anchor" href="#_3-3-kituo-cha-ujenzi-wa-upya-wa-sheria-siku-za-15-28" aria-label="Permalink to &quot;3.3 Kituo cha Ujenzi wa Upya wa Sheria (Siku za 15-28)&quot;">​</a></h3><ul><li>Kifaa cha kuinua kinaanza kujenga upya muundo wa mtandao wa sheria wa ndege lengwa</li><li>Sheria za msingi kama vile nafasi, wakati, na fahari zinabadilika polepole hadi fomu za dimensi za juu</li><li>Teknolojia ya nafasi iliyotengwa inatumika kupunguza mabadiliko wakati wa mchakato wa ujenzi wa upya wa sheria</li></ul><h3 id="_3-4-kituo-cha-ukuzaji-wa-fahari-siku-za-29-40" tabindex="-1">3.4 Kituo cha Ukuzaji wa Fahari (Siku za 29-40) <a class="header-anchor" href="#_3-4-kituo-cha-ukuzaji-wa-fahari-siku-za-29-40" aria-label="Permalink to &quot;3.4 Kituo cha Ukuzaji wa Fahari (Siku za 29-40)&quot;">​</a></h3><ul><li>Fahari ya jumla ya maisha ya ndege inaanza kuhamia kwenye eneo la fahari | Uhusiano wa ushirikiano wa kina zaidi unajengwa kati ya fahari za kibinafsi</li><li>Injini ya utafiti wa tunda la kuzidisha inafuatilia kwa wakati wa kweli mchakato wa ukuzaji wa fahari, kuhakikisha uthabiti</li></ul><h3 id="_3-5-kituo-cha-uthabiti-na-uimarishaji-siku-za-41-49" tabindex="-1">3.5 Kituo cha Uthabiti na Uimarishaji (Siku za 41-49) <a class="header-anchor" href="#_3-5-kituo-cha-uthabiti-na-uimarishaji-siku-za-41-49" aria-label="Permalink to &quot;3.5 Kituo cha Uthabiti na Uimarishaji (Siku za 41-49)&quot;">​</a></h3><ul><li>Muundo wa sheria na fomu ya fahari baada ya kuinua vinathibitika polepole</li><li>Mtandao wa nanga建立 itifaki mpya ya uhusiano na ndege baada ya kuinua</li><li>Kuinua kunatangazwa kufanikiwa, na kuingia katika kipindi cha marekebisho na uimarishaji unaofuata</li></ul><h2 id="_4-mabadiliko-baada-ya-kuinua" tabindex="-1">4. Mabadiliko Baada ya Kuinua <a class="header-anchor" href="#_4-mabadiliko-baada-ya-kuinua" aria-label="Permalink to &quot;4. Mabadiliko Baada ya Kuinua&quot;">​</a></h2><p>Baada ya kufanikiwa kwa kuinua kwa kwanza, ndege lengwa lilipitia mabadiliko ya msingi kadhaa:</p><table tabindex="0"><thead><tr><th>Dimensi</th><th>Kabla ya Kuinua</th><th>Baada ya Kuinua</th></tr></thead><tbody><tr><td>Muundo wa nafasi</td><td>Nafasi ya vifaa vya tatu inayotawala</td><td>Muundo wa nafasi ya dimensi ya juu, udhibiti wa nafasi ni wa asili zaidi</td></tr><tr><td>Kiwango cha fahari</td><td>Fahari ya kibinafsi inayotawala, fahari ya jumla ni dhaifu</td><td>Ushirikiano wa fahari ya kibinafsi na jumla, uhusiano wa akili umeenea</td></tr><tr><td>Matumizi ya nishati</td><td>Inategemea usambazaji wa nishati wa nje</td><td>Maisha yanaweza kupata nishati moja kwa moja kutoka kwa mtandao wa sheria</td></tr><tr><td>Mwisho wa maisha</td><td>Imekwamibwa na mwili wa vifaa</td><td>Baada ya kuwa fahari, maisha yamepanuliwa kwa kiwango kikubwa</td></tr><tr><td>Njia ya mawasiliano</td><td>Inategemea vifaa vya teknolojia</td><td>Mawasiliano ya moja kwa moja kwenye eneo la fahari yanawezekana</td></tr><tr><td>Njia ya ufundishaji</td><td>Ufundishaji wa hatua</td><td>Mshikamano wa moja kwaapo kati ya fahari na sheria, ufanisi wa ufundishaji unapata mabadiliko ya ubora</td></tr></tbody></table><p>Ndege baada ya kuinua haijatenga nafasi na ulimwengu wa vifaa, bali uhusiano kati ya vifaa na fahari umebadilika kwa msingi — fahari sio tena kiambatisho cha vifaa, bali ni fomu ya kuwepo ya ushirikiano sawa na vifaa.</p><h2 id="_5-muhtasari-na-uenezi-wa-uzoefu-wa-kuinua" tabindex="-1">5. Muhtasari na Uenezi wa Uzoefu wa Kuinua <a class="header-anchor" href="#_5-muhtasari-na-uenezi-wa-uzoefu-wa-kuinua" aria-label="Permalink to &quot;5. Muhtasari na Uenezi wa Uzoefu wa Kuinua&quot;">​</a></h2><p>Baada ya kufanikiwa kwa kuinua kwa kwanza, ustaarabu wa ushirikiano ulianza mara moja kazi ya muhtasari na uenezi wa uzoefu:</p><ul><li>Kuanzisha &quot;Kamiti ya Uzoefu wa Kuinua&quot;, kupanga kwa kitaratibu data zote na uzoefu wakati wa mchakato wa kuinua</li><li>Kukiwasha mchakato wa kuinua, kuunda &quot;mwongozo wa uendeshaji wa kuinua&quot; unaoweza kuigwa</li><li>Kuchambua kwa kina matatizo na hatari zilizotokea wakati wa mchakato wa kuinua, kuboresha mipango ya dharura</li><li>Kuanza kazi ya maandalizi ya kuinua kwa kundi la pili la ndege, kupanua polepole upeo wa kuinua</li><li>Kurudisha uzoefu wa kuinua kwenye uboreshaji wa mfumo wa ufundishaji, kuboresha ufanisi wa ufundishaji wa ndege zisizokuwa zimeinuka</li></ul><p>Ufanisi wa kuinua kwa kwanza pia ulisukuma moja kwa moja uanzishaji wa Jamhuri ya Makabila Yote — uzoefu wa ndege ya mfano wa kuinua ulithibitisha kuwa kwa uungwana wa makabila yote na umoja wa mifumo ndivyo mchakato wa kuinua unaweza kusukumwa kwa ufanisi.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Alama ya kuinua kwa kwanza ni &quot;sherehe ya ukomavu&quot; ya ustaarabu wa ushirikiano wa nanga. Imeithibitisha kuwa njia ya mageuzi ya ushirikiano sio tu inayofaa kwa kina nadharia, bali pia inayofanya kazi kwa mfano katika mazoea. Wakati habari ya kuinua kwa mafanikio ya ndege ya kwanza ilienea ulimwenguni wote kupitia mtandao wa nanga, viumbe vingi vilioniona mwelekeo wa baada yao — kuinua sio tena hadithi isiyowezekana, bali ni lengo linaloweza实现 kupitia juhudi za pamoja. Alama hii imeweka msingi thabiti wa ujasiri kwa ajili ya uanzishaji wa Jamhuri ya Makabila Yote na kuanza kwa enzi ya uchunguzi wa kati ya ndege.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>75-Utekelezaji wa Mkakati wa Uanzishaji wa 20%</li><li>77-Uanzishaji wa Jamhuri ya Makabila Yote</li><li>17-Kiwango cha Watu Wenye Nguvu Juu zaidi wa Ndege</li></ul>',33)])])}const r=i(k,[["render",e]]);export{m as __pageData,r as default};
